mapper.select:
SELECT TO_CHAR(A.APPLY_NO) AS APPLY_NO, A.PERSON_ID, B.EMPID, B.LOCAL_NAME, GET_DEPT_NAME(B.DEPTNO, #{lang, jdbcType=VARCHAR}) AS DEPTNAME, A.TRAINING_CONTENT, A.TRAINING_PURPOSE, TO_CHAR(A.TRAINING_TYPE) AS TRAINING_TYPE, GET_GLOBAL_NAME(A.TRAINING_TYPE, #{lang, jdbcType=VARCHAR}) AS TRAINING_TYPE_NAME, A.TRAINING_UNIT, A.TRAINING_LOCATION, TO_CHAR(A.START_DATE, 'DD/MM/YYYY') AS START_DATE, TO_CHAR(A.END_DATE, 'DD/MM/YYYY') AS END_DATE, TO_CHAR(A.AFFIRM_FLAG) AS AFFIRM_FLAG, GET_GLOBAL_NAME(A.AFFIRM_FLAG, #{lang, jdbcType=VARCHAR}) AS AFFIRM_FLAG_NAME, A.REMARK, A.TRAIN_UNIT, TO_CHAR(A.TRAIN_FEE) AS TRAIN_FEE, TO_CHAR(A.TRAIN_PRICE) AS TRAIN_PRICE, TO_CHAR(A.TRAIN_TRAINEE) AS TRAIN_TRAINEE, TO_CHAR(A.TRAIN_AMOUNT) AS TRAIN_AMOUNT, TO_CHAR(A.TRAIN_FEES_OTHER) AS TRAIN_FEES_OTHER, TO_CHAR(A.TRAIN_FEES_TOTAL) AS TRAIN_FEES_TOTAL, TO_CHAR(A.CREATE_DATE, 'DD/MM/YYYY') AS CREATE_DATE FROM EDU_TRAINING_REGISTER A JOIN HR_EMPLOYEE B ON B.PERSON_ID = A.PERSON_ID WHERE A.PERSON_ID = #{adminID, jdbcType=VARCHAR}
AND A.TRAINING_TYPE = #{trainingType, jdbcType=VARCHAR}
ORDER BY A.CREATE_DATE DESC
